B.bL4=s(["steroid","prednisolone","dexamethasone","hydrocortisone","equivalent dose","conversion"],t.s)
B.aiz=new A.c1("sbp","Systolic BP","mmHg","e.g. 100",!1,!1)
B.aiI=new A.c1("dbp","Diastolic BP","mmHg","e.g. 60",!1,!1)
B.aij=new A.c1("age","Age (for expected minimum)","years","e.g. 5",!1,!1)
